INSERT INTO public.eneatipo (id, numero_eneatipo, nombre, created_at, fecha_baja, descripcion, apodos, miedo_basico, deseo_basico, mensaje_superyo) VALUES
	('5d670e09-141c-4425-b2b4-eac4a6d9c002', 1, 'El Reformador', '2026-06-20 19:58:40.418262+00', NULL, 'El tipo idealista de sólidos principios. Las personas tipo Uno son éticas y concienzudas, poseen un fuerte sentido del bien y el mal. Son profesores y cruzados, se esfuerzan siempre por mejorar las cosas, pero temen cometer errores. Bien organizados, ordenados y meticulosos, tratan de mantener valores elevados, pero pueden resultar críticos y perfeccionistas. Normalmente tienen problemas de rabia e impaciencia reprimidas. En su mejor aspecto, el Uno sano es sabio, perceptivo, realista y noble, a la vez que moralmente heroico.', '{"EL MAESTRO","EL CRUZADO","EL MORALISTA","EL PERFECCIONISTA","EL ORGANIZADOR"}', 'Ser malo, corrupto, perverso o imperfecto', 'Ser bueno, virtuoso, equilibrado, íntegro', 'Vales o eres bueno si haces lo correcto'),
	('ecc1a4ee-3b37-4d4d-9664-e57ff366cee9', 2, 'El Ayudador', '2026-06-20 19:58:40.418262+00', NULL, 'El tipo preocupado, orientado a los demás. Los Dos son comprensivos, sinceros y bondadosos; son amistosos, generosos y abnegados, pero también pueden ser sentimentales, aduladores y obsequiosos. Desean intimar con los demás y suelen hacer cosas por ellos para sentirse necesitados. Por lo general tienen problemas para cuidar de sí mismos y reconocer sus propias necesidades. En su mejor aspecto, el Dos sano es generoso, altruista y siente un amor incondicional por sí mismo y por los demás.', '{"EL ALTRUISTA","EL AMANTE","EL CELADOR","EL COMPLACIENTE","EL PERMISOR","EL AMIGO ESPECIAL"}', 'Ser indigno de amor', 'Sentirse amado', 'Vales o estás bien si eres amado por los demás y eres amigo de ellos'),
	('4e73ab4a-d350-4f65-a470-9e72a21446a3', 3, 'El Triunfador', '2026-06-20 19:58:40.418262+00', NULL, 'El tipo adaptable y orientado al éxito. Las personas tipo Tres son seguras de sí mismas, atractivas y encantadoras. Ambiciosas, competentes y enérgicas, también pueden ser muy conscientes de su posición y estar muy motivadas por el progreso personal. Suelen preocuparse por su imagen y por lo que los demás piensan de ellas. Normalmente tienen problemas de adicción al trabajo y de competitividad. En su mejor aspecto, el Tres sano se acepta a sí mismo, es auténtico, es todo lo que aparenta ser, un modelo que inspira a otras personas.', '{"EL MOTIVADOR","EL MODELO","EL DECHADO","EL COMUNICADOR","EL BUSCADOR DE ESTATUS","«EL MEJOR»"}', 'Ser despreciable o a carecer de valor inherente', 'Sentirse valioso, aceptado y deseable', 'Vales o estás bien si tienes éxito y los demás piensan bien de ti'),
	('4c23acf6-2208-4eb9-aad6-56ddc6c6382a', 4, 'El Individualista', '2026-06-20 19:58:40.418262+00', NULL, 'El tipo romántico e introspectivo. Los tipos Cuatro son conscientes de sí mismos, sensibles, reservados y callados. Son demostrativos, sinceros y personales emocionalmente, pero también pueden ser caprichosos y tímidos. Se ocultan de los demás porque se sienten vulnerables o defectuosos, pero también pueden sentirse desdeñosos y ajenos a las formas normales de vivir. Normalmente tienen problemas de autocomplacencia y autocompasión. En su mejor aspecto, los tipos Cuatro sanos son inspirados y muy creativos, capaces de renovarse y transformar sus experiencias.', '{"EL ARTISTA","EL ROMÁNTICO","EL MELANCÓLICO","EL ESTETA","LA VÍCTIMA TRÁGICA","EL ESPECIAL"}', 'Carecer de identidad o de no ser importante', 'Descubrirse a sí mismo y su importancia; crearse una identidad a partir de su experiencia interior', 'Vales o estás bien si eres fiel a ti mismo'),
	('16c69091-c6b0-4dd5-ab6e-2b027488cdc2', 5, 'El Investigador', '2026-06-20 19:58:40.418262+00', NULL, 'El tipo vehemente y cerebral. Los Cinco son despabilados, perspicaces y curiosos. Son capaces de concentrarse y enfocar la atención en desarrollar ideas y habilidades complejas. Independientes e innovadores, es posible que se obsesionen con sus pensamientos y elaboraciones imaginarias. Se desligan de las cosas, pero son muy nerviosos y vehementes. Por lo general tienen problemas de aislamiento, excentricidad y nihilismo. En su mejor aspecto, el Cinco sano es pionero visionario, suele estar en la vanguardia y es capaz de ver el mundo de un modo totalmente nuevo.', '{"EL PENSADOR","EL INNOVADOR","EL ESPECIALISTA","EL RADICAL","EL EXPERTO","EL OBSERVADOR"}', 'Ser inútil, incapaz o incompetente', 'Ser capaz y competente', 'Vales o estás bien si eres experto en algo'),
	('9306c121-395f-4c93-b6ed-9b6cad3dcf25', 6, 'El Leal', '2026-06-20 19:58:40.418262+00', NULL, 'El tipo comprometido, orientado a la seguridad. Las personas tipo Seis son dignas de confianza, trabajadoras y responsables, pero también pueden adoptar una actitud defensiva, ser evasivas y muy nerviosas; trabajan hasta estresarse al mismo tiempo que se quejan de ello. Suelen ser cautelosas e indecisas, aunque también reactivas, desafiantes y rebeldes. Normalmente tienen problemas de inseguridad y desconfianza. En su mejor aspecto, los Seis sanos son estables interiormente, seguros de sí mismos, independientes, y apoyan con valentía a los débiles e incapaces.', '{"EL GUARDIÁN","EL FIEL CREYENTE","EL ESCÉPTICO","EL APAGAFUEGOS","EL TRADICIONALISTA","EL INCONDICIONAL"}', 'Carecer de apoyo u orientación', 'Encontrar seguridad y apoyo', 'Vales o estás bien si haces lo que se espera de ti'),
	('feac4532-ed3e-4fe5-89bd-a98cafcc75be', 7, 'El Entusiasta', '2026-06-20 19:58:40.418262+00', NULL, 'El tipo productivo y ajetreado. Los Siete son versátiles, optimistas y espontáneos; juguetones, animosos y prácticos, también podrían abarcar demasiado, ser desorganizados e indisciplinados. Constantemente buscan experiencias nuevas y estimulantes, pero la actividad continuada los aturde y agota. Por lo general tienen problemas de superficialidad e impulsividad. En su mejor aspecto, los Siete sanos centran sus dotes en objetivos dignos, son alegres, muy capacitados y muy agradecidos.', '{"EL GENERALISTA","EL MULTITAREAS","EL NIÑO PRODIGIO","EL DILETANTE","EL ENTENDIDO","EL ESTIMULADOR"}', 'Ser desvalido o quedar atrapado en el dolor', 'Estar feliz, contento, encontrar satisfacción', 'Vales o estás bien si obtienes lo que necesitas'),
	('ded93697-94cb-40e8-b4d8-02b9fc1cd7e7', 8, 'El Desafiador', '2026-06-20 19:58:40.418262+00', NULL, 'El tipo poderoso y dominante. Las personas tipo Ocho son seguras de sí mismas, fuertes y capaces de imponerse. Protectoras, ingeniosas y decididas, también resultan orgullosas y dominantes; piensan que deben estar al mando de su entorno y suelen volverse retadoras e intimidadoras. Normalmente tienen problemas para intimar con los demás. En su mejor aspecto, los Ocho sanos se controlan, usan su fuerza para mejorar la vida de otras personas, volviéndose heroicos, magnánimos y a veces históricamente grandiosos.', '{"EL LÍDER","EL PROTECTOR","EL PROVEEDOR","EL EMPRESARIO","EL INCONFORMISTA","LA ROCA"}', 'Ser dañado o controlado por otros', 'Protegerse, decidir su camino en la vida', 'Vales o estás bien si eres fuerte y estás al mando de tu situación'),
	('23fc258a-dc68-4815-a69c-8c94cf0dc416', 9, 'El Pacificador', '2026-06-20 19:58:40.418262+00', NULL, 'El tipo acomodadizo, humilde. Los tipos Nueve son conformistas, confiados y estables. Son afables, bondadosos, se acomodan con facilidad y ofrecen su apoyo, pero también pueden estar demasiado dispuestos a transigir con los demás para mantener la paz. Desean que todo vaya sobre ruedas, sin conflictos, pero tienden a ser complacientes y a minimizar cualquier cosa inquietante. Normalmente tienen problemas de pasividad y tozudez. En su mejor aspecto, los Nueve sanos son indómitos y abarcadores; son capaces de unir a las personas y solucionar conflictos.', '{"EL SANADOR","EL OPTIMISTA","EL RECONCILIADOR","EL CONSOLADOR","EL UTÓPICO","NADIE ESPECIAL"}', 'Perder la conexión, fragmentación', 'Mantener la estabilidad interior y la paz mental', 'Vales o estás bien mientras los que te rodean sean buenos y estén bien');
