	('51ef377e-e979-4b2d-8951-589a7fcf79fd', 'Bahía Fox (Is. Malvinas)', '94021010', '2026-07-09 20:27:37.821635+00', NULL, '81af966b-e26d-4883-818e-b21200e1666f'),
