	('8a10bc67-a888-4f98-803c-5076fa0a0aa0', 'Grytviken (Is Georgias del Sur)', '94021040', '2026-07-09 20:27:37.821635+00', NULL, '81af966b-e26d-4883-818e-b21200e1666f'),
	('f4801feb-3eb4-4b1f-801c-80e414821f17', 'Monte Agradable (Is. Malvinas)', '94021050', '2026-07-09 20:27:37.821635+00', NULL, '81af966b-e26d-4883-818e-b21200e1666f'),
	('c62f878c-62ae-4684-9c43-43bc9ad6fce6', 'Pradera del Ganso (Is. Malvinas)', '94021060', '2026-07-09 20:27:37.821635+00', NULL, '81af966b-e26d-4883-818e-b21200e1666f'),
	('f72f656d-7458-4732-829d-024bff743cdf', 'Puerto Argentino (Is. Malvinas)', '94021070', '2026-07-09 20:27:37.821635+00', NULL, '81af966b-e26d-4883-818e-b21200e1666f'),
