INSERT INTO public.opcion_respuesta (id, valor_numerico, texto_opcion) VALUES
	('9951a03b-2f0d-4bc4-b6f2-48fbd849f166', 1, 'Casi nunca'),
	('8fbaf7fe-915d-4d4d-bf2b-41f392017965', 2, 'Rara vez cierto'),
	('3f230052-b9b1-4b1a-afb8-ce4828f823a0', 3, 'Algo cierto'),
	('828f56c1-164a-432e-a9c1-f916377e9a8c', 4, 'Generalmente cierto'),
	('c8364451-3a52-4727-9269-2f89e923aa02', 5, 'Muy cierto');
INSERT INTO public.pregunta_eneagrama (id, numero_pregunta, enunciado, eneatipo_asociado, fecha_creacion, codigo_original, fecha_baja, pausada) VALUES
	('d00161c3-4fdd-45aa-a8f8-6bf9a4d4cc35', 8, 'Me molesta ver cómo la gente se justifica fácilmente para romper las reglas cuando les conviene.', 1, '2026-06-23 21:37:13.599964+00', '1_8', NULL, false),
	('c77a216d-00d2-4c53-9773-bb8a7d0b7cb0', 15, 'Me conmueve la nobleza de las personas y su capacidad de mantener una buena actitud en los momentos difíciles.', 1, '2026-06-23 21:37:13.599964+00', '1_15', NULL, false),
	('627da534-3a64-4708-a4ed-23c0e26a68b5', 1, 'Por lo general me consideran una persona seria y sensata, y una vez dicho y hecho todo, supongo que lo soy', 1, '2026-06-23 21:37:13.599964+00', '1_1', NULL, false),
	('07e89cb4-cd34-49de-9d08-4a82811c1e52', 3, 'Si bien una parte de mí podría ser alocada, en términos generales no ha sido precisamente ese mi estilo', 1, '2026-06-23 21:37:13.599964+00', '1_3', NULL, false),
	('bc7f006b-7e57-4e8d-9f5d-954fade5c310', 4, 'Tengo la impresión de que tengo un juez en la cabeza: a veces este juez es sabio y perspicaz, pero muchas otras es simplemente severo y duro', 1, '2026-06-23 21:37:13.599964+00', '1_4', NULL, false),
	('7912e823-ef7b-43e5-971b-a33396a8e6dd', 5, 'Creo que he pagado un elevado precio por tratar de ser perfecto', 1, '2026-06-23 21:37:13.599964+00', '1_5', NULL, false),
	('ff10e57d-5f36-4c99-945c-769f1d727dd3', 6, 'Me gusta reírme como a cualquiera; ¡debería hacerlo más a menudo!', 1, '2026-06-23 21:37:13.599964+00', '1_6', NULL, false),
	('81cc84e2-9302-45e3-b4c5-8acc835201b2', 7, 'Mis principios e ideales me estimulan hacia mayores logros y dan sentido y valor a mi vida', 1, '2026-06-23 21:37:13.599964+00', '1_7', NULL, false),
	('d3d04e27-8e28-4ceb-8f8f-2e75366297f5', 9, 'Depende tanto de mí que se hagan las cosas que tengo que ser más organizado y metódico que los demás', 1, '2026-06-23 21:37:13.599964+00', '1_9', NULL, false),
	('b397002a-3fd4-4076-b63f-40704ae3f76a', 10, 'Me imagino que tengo una misión personal, tal vez una vocación para algo superior, y creo que durante mi vida podría realizar algo extraordinario', 1, '2026-06-23 21:37:13.599964+00', '1_10', NULL, false),
	('4450fd60-7b82-4584-9e93-e15d8b02a5ec', 11, 'Detesto los errores, por lo tanto tiendo a ser muy minucioso para asegurarme de que las cosas se hagan bien', 1, '2026-06-23 21:37:13.599964+00', '1_11', NULL, false),
	('956f96af-aaaa-4ed2-9c05-376df98cab47', 12, 'Gran parte de mi vida he creído que lo que está bien, está bien, y que lo que está mal, está mal, y ya está', 1, '2026-06-23 21:37:13.599964+00', '1_12', NULL, false),
	('dff32930-67e2-4ab9-8d79-2856b69a9b5d', 13, 'Me cuesta muchísimo dejar que las cosas se hagan sólo suficientemente bien', 1, '2026-06-23 21:37:13.599964+00', '1_13', NULL, false),
	('e0a753ab-7653-4cff-803c-53c855f2f61d', 14, 'Han recaído muchas responsabilidades sobre mis hombros: si no hubiera estado a la altura de las circunstancias, sólo Dios sabe lo que habría ocurrido', 1, '2026-06-23 21:37:13.599964+00', '1_14', NULL, false),
	('8aa14882-42e2-45e2-8940-d84419f1ca7a', 16, 'Mi auténtico interés por los demás hace que me involucre profundamente con ellos, con sus esperanzas, sus sueños y necesidades', 2, '2026-06-23 21:37:13.599964+00', '2_1', NULL, false),
	('c7508115-4098-4811-a746-96c31cf308b5', 17, 'Me resulta natural ser amistoso; entablo conversaciones con facilidad y me tuteo con todo el mundo', 2, '2026-06-23 21:37:13.599964+00', '2_2', NULL, false),
	('02b02a0c-1e01-48b7-9fe1-6c1d07e0fb73', 18, 'He descubierto que las personas reaccionan con simpatía cuando les presto atención y les doy aliento', 2, '2026-06-23 21:37:13.599964+00', '2_3', NULL, false),
	('ca75fffa-31c3-4c55-91bf-1f9eccfb378c', 19, 'No puedo ver un perro extraviado en la calle sin desear llevármelo a casa', 2, '2026-06-23 21:37:13.599964+00', '2_4', NULL, false),
	('9c78d858-4678-4c86-8d50-c1e4713145cc', 20, 'Me siento bien por ser una persona considerada y generosa', 2, '2026-06-23 21:37:13.599964+00', '2_5', NULL, false),
	('826c334d-d4ea-42f2-97e3-c092030f3dfd', 22, 'Es cierto que suelo hacer más por los demás de lo que debiera; doy demasiado y no pienso en mí lo suficiente', 2, '2026-06-23 21:37:13.599964+00', '2_7', NULL, false),
	('77999947-fa1c-48cb-ad51-c5271683d2cc', 23, 'Con frecuencia me sorprendo intentando conquistar a las personas, sobre todo si al principio se muestran indiferentes a mí', 2, '2026-06-23 21:37:13.599964+00', '2_8', NULL, false),
	('f76dba41-4e7f-4e3a-a25c-c4575b03c361', 26, 'Soy capaz de expresar mis sentimientos por las personas con más franqueza que la mayoría', 2, '2026-06-23 21:37:13.599964+00', '2_11', NULL, false),
	('a05c7c07-c134-46d2-8501-2e5390415b27', 27, 'Hago un esfuerzo especial por saber qué les pasa a las personas que quiero', 2, '2026-06-23 21:37:13.599964+00', '2_12', NULL, false),
	('0e6aeecc-4178-4bfe-813c-e138a1c3a5f3', 37, 'Deseo causar buena impresión, de modo que normalmente soy cortés, educado y amigable', 3, '2026-06-23 21:37:13.599964+00', '3_7', NULL, false),
	('218fd9b7-1a79-478f-a577-74a771f8b21d', 38, 'Sé lo bien que les va a mis amigos y colegas, y tiendo a compararme con ellos', 3, '2026-06-23 21:37:13.599964+00', '3_8', NULL, false),
	('bc34b21b-d8f8-4c26-bdc5-1aa5ad564ff2', 39, 'Suelo esforzarme por ser el mejor en lo que hago; sí no puedo sobresalir en algo, por lo general no me molesto en hacerlo', 3, '2026-06-23 21:37:13.599964+00', '3_9', NULL, false),
	('e69eaec0-0bce-44d5-bda6-e6a6811a8bcd', 40, 'A veces he tenido que tomar unos pocos atajos para conseguir mis objetivos', 3, '2026-06-23 21:37:13.599964+00', '3_10', NULL, false),
	('b96e38a8-122b-44ec-a719-19b68d3e272c', 41, 'Cuando me siento inseguro puedo ser algo reservado y frío con las personas', 3, '2026-06-23 21:37:13.599964+00', '3_11', NULL, false),
	('e02926d7-c1dd-4018-884b-c1cee3bd57c6', 42, 'Claro que me molesta que los demás no reconozcan la excelencia en lo que hago', 3, '2026-06-23 21:37:13.599964+00', '3_12', NULL, false),
	('1d82777e-e44e-418a-96b2-5188031546a1', 43, 'Soy más adaptable que la mayoría: si las cosas no van bien, sé cambiar mi comportamiento para obtener los resultados que deseo', 3, '2026-06-23 21:37:13.599964+00', '3_13', NULL, false),
	('db9827af-ce7a-4639-92f0-6ea00c7eb961', 44, 'Siempre tengo un objetivo en mente, y sé motivarme para conseguirlo', 3, '2026-06-23 21:37:13.599964+00', '3_14', NULL, false),
	('69bcf5b5-6de1-4864-9bb5-52359b27069f', 45, 'Tengo una vena de adicción al trabajo; me siento perdido si no estoy realizando cosas', 3, '2026-06-23 21:37:13.599964+00', '3_15', NULL, false),
	('767a198f-dafa-4572-a619-793dc23e65dc', 46, 'Muchos me consideran una persona enigmática, difícil y contradictoria, ¡y eso me gusta de mí!', 4, '2026-06-23 21:37:13.599964+00', '4_1', NULL, false),
	('91f70165-2591-4132-b35e-02f6091cb1fa', 47, 'Tiendo a obsesionarme con mis sentimientos negativos un buen tiempo antes de liberarme de ellos', 4, '2026-06-23 21:37:13.599964+00', '4_2', NULL, false),
	('17ebed91-ff3b-4ba5-8872-257d9d75fbcb', 48, 'Suelo sentirme solo, incluso cuando estoy con personas amigas', 4, '2026-06-23 21:37:13.599964+00', '4_3', NULL, false),
	('38a75f13-24a1-401d-b75f-eeb4822d0126', 49, 'Si me critican o entienden mal, tiendo a cerrarme en mí mismo y a ponerme de mal humor', 4, '2026-06-23 21:37:13.599964+00', '4_4', NULL, false),
	('416545e3-e424-4e59-8781-0338a9e4ac79', 50, 'Me cuesta participar en proyectos si no tengo el control creativo', 4, '2026-06-23 21:37:13.599964+00', '4_5', NULL, false),
	('30990660-20dd-4ed5-b81b-fb1db1032fa8', 51, 'Tiendo a no seguir las reglas ni las expectativas porque quiero poner mi sello especial en todo lo que hago', 4, '2026-06-23 21:37:13.599964+00', '4_6', NULL, false),
	('d377ff13-cfa8-4b12-86b3-c1b94bb57787', 52, 'Según muchos criterios, soy bastante dramático y temperamental', 4, '2026-06-23 21:37:13.599964+00', '4_7', NULL, false),
	('18024c76-f4bf-4fa3-8df7-9d65e1371b12', 53, 'Tiendo a pasar bastante tiempo imaginando situaciones y conversaciones que no han ocurrido necesariamente', 4, '2026-06-23 21:37:13.599964+00', '4_8', NULL, false),
	('33e7ef79-5458-4ba8-9ad6-ad488529421e', 54, 'Ansío que alguien me rescate y me arranque de toda esta monotonía', 4, '2026-06-23 21:37:13.599964+00', '4_9', NULL, false),
	('dfa29f27-fd5f-4b76-977d-150518b41139', 55, 'Cuando las cosas se ponen difíciles, tiendo a desmoronarme y renunciar; tal vez tiro la toalla con demasiada facilidad', 4, '2026-06-23 21:37:13.599964+00', '4_10', NULL, false),
	('db3c9675-f592-45f8-bda3-92c3a576f61c', 56, 'Soy capaz de perdonarme casi cualquier cosa, menos el mal gusto', 4, '2026-06-23 21:37:13.599964+00', '4_11', NULL, false),
	('73ec7e07-3f94-4a28-a42b-40b2fe56c16f', 57, 'Por lo general, no me gusta trabajar demasiado cerca de los demás', 4, '2026-06-23 21:37:13.599964+00', '4_12', NULL, false),
	('e88d0af2-6e7d-4af9-811a-d53504c7ecbe', 58, 'Conocerme a mí mismo y ser fiel a mis necesidades emocionales han sido motivaciones muy importantes para mí', 4, '2026-06-23 21:37:13.599964+00', '4_13', NULL, false),
	('4e93ec4f-81a9-4316-a67b-8e3a6ef4516f', 60, 'Soy muy consciente de mis intuiciones, tenga o no el valor para seguirlas', 4, '2026-06-23 21:37:13.599964+00', '4_15', NULL, false),
	('f7f6b8d8-a40d-4c3a-b24b-8337930904e7', 61, 'Me gusta profundizar en las cosas, y estudio detenidamente los detalles hasta que lo he entendido todo lo mejor posible', 5, '2026-06-23 21:37:13.599964+00', '5_1', NULL, false),
	('c2d543ed-6baa-4d9d-9402-ce06164c4116', 62, 'Soy una persona muy reservada, no dejo entrar a muchas personas en mi mundo', 5, '2026-06-23 21:37:13.599964+00', '5_2', NULL, false),
	('89160236-f103-4d8e-94db-9affb1e40130', 63, 'No me siento muy importante ni poderoso, más bien pequeño e invisible: ¡Sería un buen espía!', 5, '2026-06-23 21:37:13.599964+00', '5_3', NULL, false),
	('2a56213f-a62e-4ebe-bbd4-e88f4e49c1a6', 64, 'Si los demás supieran las cosas que pienso la mayor parte del tiempo creerían que estoy loco', 5, '2026-06-23 21:37:13.599964+00', '5_4', NULL, false),
	('9ae10f6f-f7c4-4562-bbfa-44795dfa110b', 65, 'Sólo teniendo la información correcta se puede tomar una decisión racional, pero, claro, la mayoría de la gente no es muy racional', 5, '2026-06-23 21:37:13.599964+00', '5_5', NULL, false),
	('e3161698-c601-4fe3-94f2-d6806b263eed', 66, 'Mi familia me encuentra algo raro o excéntrico; ciertamente me han dicho que debo salir más', 5, '2026-06-23 21:37:13.599964+00', '5_6', NULL, false),
	('62dd4f33-6099-428c-a875-78dcd9693f13', 67, 'Hablo bastante cuando quiero, pero la mayor parte del tiempo prefiero limitarme a observar la locura que me rodea', 5, '2026-06-23 21:37:13.599964+00', '5_7', NULL, false),
	('55e1d47a-f4c6-42b1-9181-135cf38b10d4', 68, 'Si hay que resolver un problema, que me dejen trabajarlo solo y saldré con la respuesta', 5, '2026-06-23 21:37:13.599964+00', '5_8', NULL, false),
	('332594c1-b26a-4f79-8c0d-9bbd54c95126', 24, 'Me encanta ser anfitrión y recibir amigos y familiares en casa.', 2, '2026-06-23 21:37:13.599964+00', '2_9', NULL, false),
	('19bf2583-76c0-4265-a325-833c695f8611', 25, 'Soy amable y se dar apoyo, pero tengo mucha más firmeza de la que parece a simple vista', 2, '2026-06-23 21:37:13.599964+00', '2_10', NULL, false),
	('9e721bd2-fdbc-497a-b1ca-7c16eead3516', 29, 'Pongo siempre las necesidades de los demás antes que las mías, y eso me ha terminado pasando factura en la salud y en la economia.', 2, '2026-06-23 21:37:13.599964+00', '2_14', NULL, false),
	('5f4843a7-a38a-4486-85ac-ee3778139323', 34, 'Me cuesta conectar con lo que siento, me pasa algo intenso un instante, pero enseguida lo dejo atrás y sigo adelante.', 3, '2026-06-23 21:37:13.599964+00', '3_4', NULL, false),
	('c0c4bdd9-4dec-4fd5-b510-749ba2f61640', 74, 'Tengo la cabeza a mil todo el tiempo; mi mente es tan intensa y activa que a veces siento que me echa humo.', 5, '2026-06-23 21:37:13.599964+00', '5_14', NULL, false),
	('c6d639b6-a78b-48bd-a94c-3c5058774161', 31, 'Me considero una persona muy competente: en realidad, me molesta no ser eficaz y eficiente', 3, '2026-06-23 21:37:13.599964+00', '3_1', NULL, false),
	('b365c5a6-0e9e-48ac-bf00-000b6b721a8e', 77, 'Soy muy emotivo,  pero me cuesta un montón mostrarlo; se lo abro solo a mi círculo íntimo, y a veces ni a ellos.', 6, '2026-06-23 21:37:13.599964+00', '6_2', NULL, false),
	('d9b84c99-9b03-42f5-9561-f89fff0202fb', 81, 'Tengo un radar terrible: mi primera impresión de alguien suele ser definitiva y me cuesta un montón cambiar de opinión después.', 6, '2026-06-23 21:37:13.599964+00', '6_6', NULL, false),
	('c79358d4-3222-453a-b084-49696413501b', 82, 'Hay unas cuantas personas a las que admiro profundamnete, son de esas figuras que me marcan el camino.', 6, '2026-06-23 21:37:13.599964+00', '6_7', NULL, false),
	('a7290fc0-5190-4d0d-9ee0-226cdbf43dbc', 35, 'Es importante para mí sentir que tengo éxito, aunque aún no sea el éxito que deseo', 3, '2026-06-23 21:37:13.599964+00', '3_5', NULL, false),
	('8a6e4384-45e5-4930-8054-8ac7be2d3cc6', 36, 'Para bien o para mal, soy bueno para encubrir mis inseguridades; nadie adivina jamás qué siento realmente', 3, '2026-06-23 21:37:13.599964+00', '3_6', NULL, false),
	('b5a1c983-0819-4810-ac2b-53e3526b04a1', 69, 'Pensándolo bien, no se puede ser más raro que aquellos que se comportan de manera normal', 5, '2026-06-23 21:37:13.599964+00', '5_9', NULL, false),
	('bea7555e-9614-4dea-8283-013196c3595d', 70, 'Tiendo a tardar muchísimo en perfeccionar los proyectos en que trabajo', 5, '2026-06-23 21:37:13.599964+00', '5_10', NULL, false),
	('fe085c77-4af1-4f90-9dee-3ae18a3bb988', 71, 'La mayoría de las personas son increíblemente ignorantes; es asombroso que algo funcione', 5, '2026-06-23 21:37:13.599964+00', '5_11', NULL, false),
	('81092e02-2774-4854-b1c5-00a949a3169c', 72, 'Sé mucho sobre muchas cosas, y en algunos campos me considero un experto', 5, '2026-06-23 21:37:13.599964+00', '5_12', NULL, false),
	('f5c8eadf-acc7-4f14-9aa0-b134add0a931', 73, 'Soy muy curioso y me gusta investigar por qué las cosas son como son; incluso las cosas obvias no son tan obvias si se miran bien', 5, '2026-06-23 21:37:13.599964+00', '5_13', NULL, false),
	('54fac4ef-1a27-447a-9c71-c01ebe45f44e', 75, 'Me concentro tanto en lo que hago que suelo no enterarme del paso del tiempo', 5, '2026-06-23 21:37:13.599964+00', '5_15', NULL, false),
	('fc884c19-094b-4d86-a88f-eba3548002e8', 76, 'Me atrae la autoridad, pero al mismo tiempo desconfío de ella', 6, '2026-06-23 21:37:13.599964+00', '6_1', NULL, false),
	('ce6106a9-a99e-4d62-ab7c-2cb4a2ac91a2', 78, 'Si cometo un error temo que todos me van a criticar de inmediato', 6, '2026-06-23 21:37:13.599964+00', '6_3', NULL, false),
	('0a207796-ea2e-48a6-89f7-e9b46a6e8384', 79, 'Me siento más seguro haciendo lo que se espera de mí que obrando por mi cuenta', 6, '2026-06-23 21:37:13.599964+00', '6_4', NULL, false),
	('9f740b42-0d72-47a3-b33d-26e3ace3297f', 80, 'Es posible que no siempre esté de acuerdo con las reglas, y que no siempre las siga, pero deseo conocerlas', 6, '2026-06-23 21:37:13.599964+00', '6_5', NULL, false),
	('afa86ff6-4c44-47f8-979b-ca052a5b566b', 83, 'No me gusta tomar grandes decisiones, pero ciertamente no deseo que otra persona las tome por mí', 6, '2026-06-23 21:37:13.599964+00', '6_8', NULL, false),
	('eda5fe39-a900-4cdd-a01f-361fe32fd0cd', 84, 'Algunas personas me consideran muy inquieto y nervioso, ¡pero no saben ni la mitad!', 6, '2026-06-23 21:37:13.599964+00', '6_9', NULL, false),
	('bf706d8b-6ec8-4666-b074-eb51b43194d0', 85, 'Sé cuánto enredo armo yo, de modo que encuentro lógico desconfiar de lo que pretenden los demás', 6, '2026-06-23 21:37:13.599964+00', '6_10', NULL, false),
	('cec7754a-2d4c-42bd-8d58-9254f91c10ee', 87, 'Soy muy trabajador, de verdad: no paro hasta terminar un trabajo', 6, '2026-06-23 21:37:13.599964+00', '6_12', NULL, false),
	('dbc48ff5-e4de-4ae5-a5cd-04d021749a4c', 88, 'Cuando tengo que tomar una decisión importante, consulto la opinión de las personas en que confío', 6, '2026-06-23 21:37:13.599964+00', '6_13', NULL, false),
	('e84b1015-4b0e-4148-8431-6ff5e9811c61', 90, 'Ansiedad podría ser mi segundo apellido', 6, '2026-06-23 21:37:13.599964+00', '6_15', NULL, false),
	('a6c78bb6-340e-4126-91f4-4e1446bf58a2', 91, 'Me encanta viajar y descubrir diferentes tipos de comidas, personas y experiencias, ¡todo el fabuloso torbellino de la vida!', 7, '2026-06-23 21:37:13.599964+00', '7_1', NULL, false),
	('62e0af44-66cc-4716-b9f3-faff9b07cdeb', 93, 'Lo importante para mi es la emoción y la variedad, no la comodidad ni la precaución, aunque aprovecho las comodidades siempre que las encuentro', 7, '2026-06-23 21:37:13.599964+00', '7_3', NULL, false),
	('57b2f476-29a5-40ca-9456-9431924c6265', 94, 'Mi mente no para de parlotear, a veces me parece que estoy pensando en diez cosas al mismo tiempo', 7, '2026-06-23 21:37:13.599964+00', '7_4', NULL, false),
	('ae512ef6-c9eb-4639-a2e5-088bb73492ca', 95, 'Una cosa que no soporto de ninguna manera es el aburrimiento, y procuro no aburrirme nunca', 7, '2026-06-23 21:37:13.599964+00', '7_5', NULL, false),
	('98b12eef-4d04-45ec-a2c7-d906d791591f', 96, 'Me comprometo bastante cuando estoy en una relación, pero cuando se acaba, paso a otra cosa', 7, '2026-06-23 21:37:13.599964+00', '7_6', NULL, false),
	('0adf7e83-53c6-4f8c-8286-1b2874f16ca5', 21, 'Me molesta mucho esforzarme tanto por los demás y sentir que ni siquiera se dan cuenta o no les importa.', 2, '2026-06-23 21:37:13.599964+00', '2_6', NULL, false),
	('9f5eeae4-013c-4665-a7fe-c180a96c0757', 2, 'Siempre he intentado ser sincero y objetivo respecto a mí mismo, y estoy decidido a ser fiel a mi conciencia, cueste lo que cueste', 1, '2026-06-23 21:37:13.599964+00', '1_2', NULL, false),
	('c68246fa-7ab8-47d5-990d-d38513c2f46a', 28, 'Me considero algo así como un «sanador de corazones rotos» . Me duele ver mal a los demás y enseguida me muevo para arreglarlo o hacerlos sentir mejor.', 2, '2026-06-23 21:37:13.599964+00', '2_13', NULL, false),
	('6a214f04-0117-4b91-8e00-8fbdeb6393f7', 30, 'Pongo toda mi energía en cuidar a los demás y hacer que se sientan especiales y queridos.', 2, '2026-06-23 21:37:13.599964+00', '2_15', NULL, false),
	('726ee92f-87cb-4c27-9fbb-b7303ff86577', 33, 'Trato de mostrar siempre mi mejor cara frente a los demás, pero bueno... ¿quién no quiere dejar una buena impresión?', 3, '2026-06-23 21:37:13.599964+00', '3_3', NULL, false),
	('639a7577-dac0-4d11-b78e-ca992d7615af', 32, 'Cuando las cosas me salen bien, se me nota: brillo, disfruto el éxito y  siento una profunda satisfacción por lo que soy y lo que conseguí.', 3, '2026-06-23 21:37:13.599964+00', '3_2', NULL, false),
	('19dd0f29-d249-43ea-a85c-6ceda9b2364f', 86, 'Quiero confiar en la gente, pero por lo general termino desconfiando y buscándole la quinta pata al gato a lo que hacen.', 6, '2026-06-23 21:37:13.599964+00', '6_11', NULL, false),
	('60583030-d5c5-4dab-ad59-2ef41ea7b52e', 89, 'Es muy raro: puedo ser súper desconfiado y analítico con todo  y de pronto me dejo engañar totalmente en algo.', 6, '2026-06-23 21:37:13.599964+00', '6_14', NULL, false),
	('0ff45fbf-d92c-4ed0-a59e-f36b41ee01bb', 92, 'Mi agenda suele estar llena, y me encanta así: No me quedo quieto, si paro, me aburro.', 7, '2026-06-23 21:37:13.599964+00', '7_2', NULL, false),
	('478052b4-172e-4da3-9f80-5d37faea8f58', 98, 'Cuando pierdo el interés o el entusiasmo por algo, prefiero abandonarla y buscar nuevos rumbos.', 7, '2026-06-23 21:37:13.599964+00', '7_8', NULL, false),
	('b1dcb7b8-ea87-4235-bfc4-a3396864bb70', 59, 'No me va ni que me manden ni andar mandando a otros; necesito mi libertad para hacer las cosas a mi manera.', 4, '2026-06-23 21:37:13.599964+00', '4_14', NULL, false),
	('7697127d-37ff-4043-a52c-6a0f7c4e92f6', 97, 'Soy curioso y arriesgado; por lo general, soy el primero entre mis amigos en probar cualquier cosa nueva e interesante', 7, '2026-06-23 21:37:13.599964+00', '7_7', NULL, false),
	('413736fa-45ec-4224-8524-9b293cfca222', 99, 'No soy sólo una «persona divertida», también tengo mi lado serio, incluso oscuro, aunque no me gusta mucho ir allí', 7, '2026-06-23 21:37:13.599964+00', '7_9', NULL, false),
	('2953637c-53ec-4cb6-ab1a-67246504f5fa', 100, 'Soy bueno para lo general, no tanto para los detalles; disfruto más teniendo muchas ideas que en ocuparme de ponerlas en práctica', 7, '2026-06-23 21:37:13.599964+00', '7_10', NULL, false),
	('df8a5038-a6f5-4e38-be2b-e0711f11ea98', 101, 'Cuando de veras deseo algo, normalmente encuentro la manera de obtenerlo', 7, '2026-06-23 21:37:13.599964+00', '7_11', NULL, false),
	('c9c7ca74-fd8e-45ba-9a1d-1bcf8e255a74', 103, 'Uno de mis principales problemas es que me distraigo con facilidad y me disperso demasiado', 7, '2026-06-23 21:37:13.599964+00', '7_13', NULL, false),
	('c0f1573b-3a57-47cf-bd42-9f2a7dac7573', 104, 'Tiendo a gastar más dinero del que probablemente debería', 7, '2026-06-23 21:37:13.599964+00', '7_14', NULL, false),
	('33385c8e-4d3a-4c30-89a4-ca847529f91e', 105, 'Me encanta estar con gente, siempre que quieran ir donde yo voy', 7, '2026-06-23 21:37:13.599964+00', '7_15', NULL, false),
	('697b7fc8-1db8-4be9-8376-f43d34e1bd34', 106, 'Soy extraordinariamente independiente y no me gusta depender de nadie para lo que necesito', 8, '2026-06-23 21:37:13.599964+00', '8_1', NULL, false),
	('cc4e8b20-1007-4f68-93e8-d828d4c64d9f', 108, 'Cuando quiero a las personas las considero «mi gente» y siento la necesidad de cuidar de sus intereses', 8, '2026-06-23 21:37:13.599964+00', '8_3', NULL, false),
	('928e2461-29ed-4ebf-839c-3f223bf566fe', 109, 'Sé cómo obtener resultados, sé cómo recompensar y apremiar a las personas para que hagan las cosas', 8, '2026-06-23 21:37:13.599964+00', '8_4', NULL, false),
	('ff6d8083-c727-43f3-bb6a-7e1d23284adb', 110, 'No siento mucha compasión por los débiles y los indecisos: la debilidad sólo atrae problemas', 8, '2026-06-23 21:37:13.599964+00', '8_5', NULL, false),
	('ce9c3433-3f84-4e3d-a739-aaf598098d7f', 111, 'Tengo una voluntad fuerte y no renuncio ni me echo atrás fácilmente', 8, '2026-06-23 21:37:13.599964+00', '8_6', NULL, false),
	('d7ebbcaa-dc17-4775-88bc-697ac718894f', 113, 'Tengo un lado tierno, incluso algo sentimental, que muestro a muy pocas personas', 8, '2026-06-23 21:37:13.599964+00', '8_8', NULL, false),
	('18d41a0a-016a-4f53-b4f3-56cb24f1c086', 114, 'Las personas que me conocen me agradecen que les hable francamente y les diga exactamente lo que pienso', 8, '2026-06-23 21:37:13.599964+00', '8_9', NULL, false),
	('def59d0c-d753-4bb7-898a-f535d2bb0695', 115, 'He tenido que trabajar mucho por todo lo que tengo; creo que las dificultades son buenas porque te endurecen y te hacen tener claro lo que deseas', 8, '2026-06-23 21:37:13.599964+00', '8_10', NULL, false),
	('86a5e005-9822-4a16-8fc8-c12143d0a720', 116, 'Me considero un desafiador, una persona que saca a las personas de su zona de comodidad para que hagan todo lo que son capaces de hacer', 8, '2026-06-23 21:37:13.599964+00', '8_11', NULL, false),
	('c6f8c6b8-01db-40cf-aaaf-93e519989615', 117, 'Mi sentido del humor es prosaico, incluso grosero a veces, aunque creo que la mayoría de las personas son demasiado remilgadas y sensibles', 8, '2026-06-23 21:37:13.599964+00', '8_12', NULL, false),
	('b5f61e6e-95e5-4373-95d5-262bf1cc863b', 119, 'Me siento más vivo cuando hago lo que los demás creen imposible: Me gusta arriesgarme y comprobar si soy capaz de vencer los peligros', 8, '2026-06-23 21:37:13.599964+00', '8_14', NULL, false),
	('402e4fc9-ec2d-4b47-adab-1735f3097df5', 120, 'Normalmente a alguien tiene que tocarle la situación desventajosa, y no quiero ser yo', 8, '2026-06-23 21:37:13.599964+00', '8_15', NULL, false),
	('8e4cb55f-56ff-4b91-8754-a819d4c94abf', 122, 'No me importa estar con gente ni me importa estar solo; cualquiera de las dos cosas me va bien, siempre que esté en paz conmigo mismo', 9, '2026-06-23 21:37:13.599964+00', '9_2', NULL, false),
	('d9afbf75-06c1-40b2-9a1e-c24cb802ee7e', 123, 'He encontrado un cierto equilibrio en mí vida, y no veo ningún motivo para estropearlo', 9, '2026-06-23 21:37:13.599964+00', '9_3', NULL, false),
	('e7189921-0e89-45ca-8c43-05c2032e0a2e', 124, 'Estar «cómodo» en todo el sentido de la palabra me atrae muchísimo', 9, '2026-06-23 21:37:13.599964+00', '9_4', NULL, false),
	('a16c938a-ecdc-4c2c-9eaf-811c747ebcc8', 125, 'Prefiero ceder antes que armar una escena', 9, '2026-06-23 21:37:13.599964+00', '9_5', NULL, false),
	('a8a1fee4-ef96-460a-881e-d2a6a68861c2', 126, 'No sé exactamente cómo lo hago, pero no me dejo deprimir por las cosas', 9, '2026-06-23 21:37:13.599964+00', '9_6', NULL, false),
	('bded54ac-39f6-4c90-b8cc-6098806dc732', 127, 'Soy bastante fácil de complacer y normalmente creo que lo que tengo es suficiente para mí', 9, '2026-06-23 21:37:13.599964+00', '9_7', NULL, false),
	('164c2b4b-5fd1-485f-8e3a-d5c47ace8f8a', 128, 'Me han dicho que parezco distraído; la verdad es que comprendo las cosas, pero no quiero reaccionar a ellas', 9, '2026-06-23 21:37:13.599964+00', '9_8', NULL, false),
	('1fcc3633-acd4-4eab-ab71-c35f0f29d285', 131, 'Hay que aceptar lo que trae la vida, ya que de todos modos no es mucho lo que se puede hacer al respecto', 9, '2026-06-23 21:37:13.599964+00', '9_11', NULL, false),
	('e420a0ca-f7bf-4533-9379-e3b541f53dba', 132, 'Me es fácil comprender diferentes puntos de vista y tiendo más a estar de acuerdo que en desacuerdo con las personas', 9, '2026-06-23 21:37:13.599964+00', '9_12', NULL, false),
	('69390d3a-40a1-47c6-8868-c863a3329679', 133, 'Prefiero acentuar lo positivo antes que insistir en lo negativo', 9, '2026-06-23 21:37:13.599964+00', '9_13', NULL, false),
	('0fb85cea-dfa1-4356-9add-a0b0b8bfb28f', 135, 'Durante el día hago todo lo que hay que hacer, pero cuando se acaba el día sé relajarme y tomarme las cosas con calma', 9, '2026-06-23 21:37:13.599964+00', '9_15', NULL, false),
	('3ee913fa-013c-4221-8f9d-8c41724e15e3', 102, 'Me puede agarrar un bajón cada tanto, pero recupero el optimismo rápidamente.', 7, '2026-06-23 21:37:13.599964+00', '7_12', NULL, false),
	('8a1cae3d-92c1-4b30-8270-2ab9f155abc5', 107, 'Entiendo que para lograr resultados importantes hay que tomar decisiones drásticas y asumir ciertos costos', 8, '2026-06-23 21:37:13.599964+00', '8_2', NULL, false),
	('df5947cc-efeb-481f-9932-c035efba01d4', 112, 'No hay nada que me haga sentir más orgulloso que ver actuar por su cuenta a quienes decidí respaldar y acompañar.', 8, '2026-06-23 21:37:13.599964+00', '8_7', NULL, false),
	('e9d0a831-7425-40a1-b25b-27ef39ea5e35', 118, 'Puedo tener explosiones de bronca muy fuertes, pero se me pasa enseguida y sigo adelante.', 8, '2026-06-23 21:37:13.599964+00', '8_13', NULL, false),
	('d3280a11-7928-448e-bae8-329daade73a6', 129, 'No me considero terco, pero me han dicho que cuando se me pone algo en la cabeza, no hay con qué darle.', 9, '2026-06-23 21:37:13.599964+00', '9_9', NULL, false),
	('4e894037-9d55-40d5-8585-672fe008e0bb', 121, 'Parece que lo que la gente más valora de mí es que se sienten seguros y tranquilos.', 9, '2026-06-23 21:37:13.599964+00', '9_1', NULL, false),
	('4f3ad171-a539-46e3-a804-c1a50a2dda61', 130, 'La gente suele alterarse con facilidad ante los problemas, mientras que yo suelo conservar la calma y la objetividad', 9, '2026-06-23 21:37:13.599964+00', '9_10', NULL, false),
	('cad23f65-2466-4190-92a4-f95e84349686', 134, 'Cuento con una visión de la vida que me orienta y me aporta muchísima paz cuando las cosas se ponen difíciles.', 9, '2026-06-23 21:37:13.599964+00', '9_14', NULL, false);
