	('10467780-0079-49ff-90e3-a0424ec8a863', 'Agropecuario', '2026-06-20 19:58:40.418262+00', NULL),
	('9ef20f9b-5874-4896-bc97-cb6981af5d76', 'Energía y Minería', '2026-06-20 19:58:40.418262+00', NULL),
