INSERT INTO public.terminos_y_condiciones (id, version, descripcion, fecha_publicacion, fecha_baja_tyc) VALUES
	('58b433fe-073c-4504-bc55-13dfb5f30a58', '0.0', 'Terminos y condiciones', '2026-07-06 22:38:04.044676+00', NULL);
